#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = VolumetricHeatCapacity::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            VolumetricHeatCapacity::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in VolumetricHeatCapacityUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        VolumetricHeatCapacity::from_base(0.0).auto_unit().unit,
        VolumetricHeatCapacityUnit::JoulePerCubicMeterKelvin
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "J/(m³·K)".parse::<VolumetricHeatCapacityUnit>(),
        Ok(VolumetricHeatCapacityUnit::JoulePerCubicMeterKelvin)
    );
    assert_eq!(
        format!("2.5 {}", "J/(m³·K)").parse::<VolumetricHeatCapacity>(),
        Ok(VolumetricHeatCapacity::new(
            2.5,
            VolumetricHeatCapacityUnit::JoulePerCubicMeterKelvin
        ))
    );
    assert_eq!(
        "kJ/(m³·K)".parse::<VolumetricHeatCapacityUnit>(),
        Ok(VolumetricHeatCapacityUnit::KilojoulePerCubicMeterKelvin)
    );
    assert_eq!(
        format!("2.5 {}", "kJ/(m³·K)").parse::<VolumetricHeatCapacity>(),
        Ok(VolumetricHeatCapacity::new(
            2.5,
            VolumetricHeatCapacityUnit::KilojoulePerCubicMeterKelvin
        ))
    );
    assert_eq!(
        "MJ/(m³·K)".parse::<VolumetricHeatCapacityUnit>(),
        Ok(VolumetricHeatCapacityUnit::MegajoulePerCubicMeterKelvin)
    );
    assert_eq!(
        format!("2.5 {}", "MJ/(m³·K)").parse::<VolumetricHeatCapacity>(),
        Ok(VolumetricHeatCapacity::new(
            2.5,
            VolumetricHeatCapacityUnit::MegajoulePerCubicMeterKelvin
        ))
    );
    assert_eq!(
        "J/(m³·°C)".parse::<VolumetricHeatCapacityUnit>(),
        Ok(VolumetricHeatCapacityUnit::JoulePerCubicMeterDegreeCelsius)
    );
    assert_eq!(
        format!("2.5 {}", "J/(m³·°C)").parse::<VolumetricHeatCapacity>(),
        Ok(VolumetricHeatCapacity::new(
            2.5,
            VolumetricHeatCapacityUnit::JoulePerCubicMeterDegreeCelsius
        ))
    );
    assert_eq!(
        "kJ/(m³·°C)".parse::<VolumetricHeatCapacityUnit>(),
        Ok(VolumetricHeatCapacityUnit::KilojoulePerCubicMeterDegreeCelsius)
    );
    assert_eq!(
        format!("2.5 {}", "kJ/(m³·°C)").parse::<VolumetricHeatCapacity>(),
        Ok(VolumetricHeatCapacity::new(
            2.5,
            VolumetricHeatCapacityUnit::KilojoulePerCubicMeterDegreeCelsius
        ))
    );
    assert_eq!(
        "MJ/(m³·°C)".parse::<VolumetricHeatCapacityUnit>(),
        Ok(VolumetricHeatCapacityUnit::MegajoulePerCubicMeterDegreeCelsius)
    );
    assert_eq!(
        format!("2.5 {}", "MJ/(m³·°C)").parse::<VolumetricHeatCapacity>(),
        Ok(VolumetricHeatCapacity::new(
            2.5,
            VolumetricHeatCapacityUnit::MegajoulePerCubicMeterDegreeCelsius
        ))
    );
    assert_eq!(
        "cal/(cm³·°C)".parse::<VolumetricHeatCapacityUnit>(),
        Ok(VolumetricHeatCapacityUnit::CaloriePerCubicCentimeterDegreeCelsius)
    );
    assert_eq!(
        format!("2.5 {}", "cal/(cm³·°C)").parse::<VolumetricHeatCapacity>(),
        Ok(VolumetricHeatCapacity::new(
            2.5,
            VolumetricHeatCapacityUnit::CaloriePerCubicCentimeterDegreeCelsius
        ))
    );
    assert_eq!(
        "kcal/(cm³·°C)".parse::<VolumetricHeatCapacityUnit>(),
        Ok(VolumetricHeatCapacityUnit::KilocaloriePerCubicCentimeterDegreeCelsius)
    );
    assert_eq!(
        format!("2.5 {}", "kcal/(cm³·°C)").parse::<VolumetricHeatCapacity>(),
        Ok(VolumetricHeatCapacity::new(
            2.5,
            VolumetricHeatCapacityUnit::KilocaloriePerCubicCentimeterDegreeCelsius
        ))
    );
    assert_eq!(
        "BTU/(ft³·°F)".parse::<VolumetricHeatCapacityUnit>(),
        Ok(VolumetricHeatCapacityUnit::BtuPerCubicFootDegreeFahrenheit)
    );
    assert_eq!(
        format!("2.5 {}", "BTU/(ft³·°F)").parse::<VolumetricHeatCapacity>(),
        Ok(VolumetricHeatCapacity::new(
            2.5,
            VolumetricHeatCapacityUnit::BtuPerCubicFootDegreeFahrenheit
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<VolumetricHeatCapacity>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = VolumetricHeatCapacity::from_base(6.0);
    let b = VolumetricHeatCapacity::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = VolumetricHeatCapacity::<i64>::from_base(7);
    let b = VolumetricHeatCapacity::<i64>::from_base(2);
    assert_eq!(a + b, VolumetricHeatCapacity::from_base(9));
    assert_eq!(a % b, VolumetricHeatCapacity::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<VolumetricHeatCapacity<i64>>(),
        VolumetricHeatCapacity::from_base(9)
    );
}
